const crypto = require('crypto');
const headers = $json.headers ?? {};
const rawBody = $json.rawBody ?? JSON.stringify($json.body ?? $json);
const timestamp = headers['x-servicedesk-timestamp'];
const signature = headers['x-servicedesk-signature'];
const secret = $env.SERVICEDESK_WEBHOOK_SECRET;
if (!timestamp || !signature || !signature.startsWith('sha256=') || !secret) { throw new Error('missing-signature'); }
const ageMs = Math.abs(Date.now() - Date.parse(timestamp));
if (ageMs > 300000) { throw new Error('stale-signature'); }
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
if (signature.slice('sha256='.length) !== expected) { throw new Error('signature-mismatch'); }
return [{ json: JSON.parse(rawBody) }];

// Use event id as the dedupe key in a real n8n datastore before notifying staff.
// ServiceDesk remains source of truth; this workflow must not mutate booking/payment state.
return [{ json: { eventId: $json.id, bookingId: $json.payload?.bookingId, received: true, sourceOfTruth: 'servicedesk' } }];
